script.code:
const inp = $workflow.input || {};
const src = inp.requestSource || 'CreateClaimShell';
const scenario = inp.scenario || 'Standard';
const runId = inp.runId || '5182';
const claimReference = inp.claimReference || ('CLAIM-' + runId);

const SCENARIOS = {
  Standard: {
    claimantName: 'Joseph Thompson',
    incidentLocation: 'A4155 Caversham Road junction with Vastern Road, Reading',
    injuryTypeCode: 'WHIPLASH',
    injuryDescription: 'a neck and lower back soft tissue injury sustained as a driver in a rear-end collision at a signalled junction',
    independentLivingFlag: true,
    activeDamageFlag: false,
    vulnerableCustomerFlag: false,
    reserveGeneralDamages: 8500,
    reserveSpecialDamages: 2200,
    reserveCareAndRehab: 0
  },
  Displaced: {
    claimantName: 'Thomas Okafor',
    incidentLocation: 'Wilmslow Road pedestrian crossing at Birchwood Avenue, Manchester',
    injuryTypeCode: 'HEAD_INJURY',
    injuryDescription: 'a traumatic head injury and multiple rib fractures sustained as a pedestrian struck on a marked crossing, with an eleven day inpatient admission',
    independentLivingFlag: false,
    activeDamageFlag: true,
    vulnerableCustomerFlag: true,
    reserveGeneralDamages: 65000,
    reserveSpecialDamages: 18000,
    reserveCareAndRehab: 4500
  },
  Underinsured: {
    claimantName: 'Priya Chandrasekaran',
    incidentLocation: 'Mill Lane junction with Otley Road, Leeds',
    injuryTypeCode: 'FRACTURE',
    injuryDescription: 'a displaced tibia and fibula fracture sustained when a cyclist was struck by a vehicle emerging from a side road',
    independentLivingFlag: true,
    activeDamageFlag: false,
    vulnerableCustomerFlag: false,
    reserveGeneralDamages: 22000,
    reserveSpecialDamages: 4000,
    reserveCareAndRehab: 0
  },
  Investigated: {
    claimantName: 'Daniel Foster',
    incidentLocation: 'Kestrel Road car park exit, Bristol',
    injuryTypeCode: 'SOFT_TISSUE',
    injuryDescription: 'a low speed shunt reported as a soft tissue back and shoulder injury, notified nine days after the accident with no police report on file and a large lost earnings claim',
    independentLivingFlag: true,
    activeDamageFlag: false,
    vulnerableCustomerFlag: false,
    reserveGeneralDamages: 1500,
    reserveSpecialDamages: 12000,
    reserveCareAndRehab: 0
  },
  Declined: {
    claimantName: 'Helen Marsh',
    incidentLocation: 'Riverside Court loading yard, Shrewsbury',
    injuryTypeCode: 'PSYCHOLOGICAL',
    injuryDescription: 'a psychological injury claimed after a workplace vehicle incident, notified 75 days after the accident on a policy where liability cover had already lapsed',
    independentLivingFlag: false,
    activeDamageFlag: true,
    vulnerableCustomerFlag: false,
    reserveGeneralDamages: 0,
    reserveSpecialDamages: 0,
    reserveCareAndRehab: 0
  },
  Reopened: {
    claimantName: 'George Whitfield',
    incidentLocation: 'Orchard Way roundabout approach, Norwich',
    injuryTypeCode: 'WHIPLASH',
    injuryDescription: 'a whiplash and lower back injury sustained as a driver rear-ended while stationary at a roundabout',
    independentLivingFlag: true,
    activeDamageFlag: false,
    vulnerableCustomerFlag: false,
    reserveGeneralDamages: 9200,
    reserveSpecialDamages: 1800,
    reserveCareAndRehab: 0
  }
};

const s = SCENARIOS[scenario] || SCENARIOS.Standard;

const out = {
  claimReference: '',
  claimantName: '',
  incidentLocation: '',
  injuryTypeCode: '',
  claimStatus: '',
  independentLivingFlag: false,
  activeDamageFlag: false,
  vulnerableCustomerFlag: false,
  reserveGeneralDamages: 0,
  reserveSpecialDamages: 0,
  reserveCareAndRehab: 0,
  closureReasonCode: '',
  complaintRef: '',
  explanation: ''
};

if (src === 'CreateClaimShell') {
  out.claimReference = claimReference;
  out.claimantName = s.claimantName;
  out.incidentLocation = s.incidentLocation;
  out.injuryTypeCode = s.injuryTypeCode;
  out.claimStatus = 'Registered';
  out.explanation = 'Claim shell opened for ' + s.claimantName + ' at ' + s.incidentLocation + ' following ' + s.injuryDescription + '.';
} else if (src === 'ScopeAndSettlement') {
  const rawBasis = inp.liabilityBasisCode ? String(inp.liabilityBasisCode) : s.injuryTypeCode;
  const basisKey = rawBasis.toLowerCase().replace(/[^a-z]/g, '');
  let generalDamages = 8400;
  let quantumSummary = 'Whiplash and neck soft tissue injury valued on the judicial guidelines bracket for a recovery period of up to two years';
  if (basisKey === 'headinjury' || basisKey === 'pedestrianstruck' || basisKey === 'failuretostop') { generalDamages = 64500; quantumSummary = 'Traumatic head injury with ongoing cognitive deficit, valued on the judicial guidelines bracket for moderate brain injury'; }
  else if (basisKey === 'fracture' || basisKey === 'failuretogiveway') { generalDamages = 21200; quantumSummary = 'Displaced lower limb fracture with residual restriction, valued on the judicial guidelines bracket for a serious leg injury'; }
  else if (basisKey === 'psychological') { generalDamages = 12750; quantumSummary = 'Moderate psychological injury valued on the judicial guidelines bracket, subject to a supportive psychiatric report'; }
  let medicalAndEarningsCost = 6200;
  if (scenario === 'Displaced') { medicalAndEarningsCost = 15800; }
  else if (scenario === 'Underinsured') { medicalAndEarningsCost = 9600; }
  let careAndRehabCost = 2800;
  if (scenario === 'Displaced') { careAndRehabCost = 11400; }
  else if (scenario === 'Investigated') { careAndRehabCost = 4600; }
  else if (scenario === 'Reopened') { careAndRehabCost = 3200; }
  const contributoryApplied = inp.contributoryNegligenceFlag === true;
  const factor = contributoryApplied ? 0.7 : 1;
  const total = Math.round((generalDamages + medicalAndEarningsCost + careAndRehabCost) * factor);
  let basis = 'Full Liability';
  let path = 'Negotiated Settlement';
  if (contributoryApplied) { basis = 'Reduced for Contributory Negligence'; path = 'Part 36 Offer'; }
  else if (scenario === 'Investigated') { path = 'Settlement Pending Investigation'; }
  else if (scenario === 'Declined') { basis = 'Without Prejudice'; path = 'Part 36 Offer'; }
  else if (scenario === 'Reopened') { path = 'Settlement Pending Investigation'; }
  out.estimatedCost = total;
  out.settlementBasis = basis;
  out.settlementPath = path;
  out.scopeOfWorksSummary = quantumSummary;
  out.explanation = 'Quantum assembled: ' + generalDamages + ' general damages, ' + medicalAndEarningsCost + ' medical costs and lost earnings, ' + careAndRehabCost + ' care and rehabilitation' + (contributoryApplied ? ', reduced for contributory negligence to ' : ', totalling ') + total + '.';
} else if (src === 'CaptureLossDetail') {
  out.independentLivingFlag = s.independentLivingFlag;
  out.activeDamageFlag = s.activeDamageFlag;
  out.vulnerableCustomerFlag = s.vulnerableCustomerFlag;
  out.explanation = 'Accident and injury detail captured: ' + s.injuryDescription + (s.independentLivingFlag ? '. The claimant is managing unaided at home.' : '. The claimant cannot manage unaided and needs daily support.');
} else if (src === 'ConfirmRegistration') {
  out.reserveGeneralDamages = s.reserveGeneralDamages;
  out.reserveSpecialDamages = s.reserveSpecialDamages;
  out.reserveCareAndRehab = s.reserveCareAndRehab;
  out.claimStatus = (scenario === 'Displaced') ? 'Open - Serious Injury Lane' : 'Open';
  out.explanation = 'Registration confirmed with opening reserves of ' + s.reserveGeneralDamages + ' general damages and ' + s.reserveSpecialDamages + ' special damages.';
} else if (src === 'RequestEvidence') {
  out.claimStatus = 'Awaiting Evidence';
  out.explanation = 'Medical evidence and special damages schedule requested from the claimant representative for claim ' + claimReference + '.';
} else if (src === 'RecordCoverageDecision') {
  const liabilityOutcome = inp.liabilityOutcome || 'Covered';
  out.claimStatus = 'Liability Recorded: ' + liabilityOutcome;
  out.explanation = 'Liability decision recorded as ' + liabilityOutcome + ' for claim ' + claimReference + '.';
} else if (src === 'ReconcileInvoices') {
  out.claimStatus = 'Invoices Reconciled';
  out.explanation = 'Treatment and rehabilitation provider invoices reconciled against the agreed treatment plan for claim ' + claimReference + '.';
} else if (src === 'CheckSubjectivities') {
  const open = (scenario === 'Investigated');
  out.closureReasonCode = open ? 'OPEN_SUBJECTIVITIES' : 'CLEAR';
  out.claimStatus = open ? 'Subjectivities Outstanding' : 'Ready to Close';
  out.explanation = open ? 'Outstanding subjectivities remain open pending investigation sign-off.' : 'No outstanding subjectivities remain; the claim is ready to close.';
} else if (src === 'ArchiveClaim') {
  out.claimStatus = 'Closed';
  out.explanation = 'Claim ' + claimReference + ' archived and closed.';
} else if (src === 'IssueAdverseDecision') {
  out.closureReasonCode = (scenario === 'Declined') ? 'LIABILITY_COVER_NOT_IN_FORCE' : 'LIABILITY_DENIED';
  out.explanation = 'Adverse decision notice issued for claim ' + claimReference + ' with closure reason ' + out.closureReasonCode + '.';
} else if (src === 'UpdateSupplementalReserve') {
  out.reserveGeneralDamages = s.reserveGeneralDamages + 3500;
  out.explanation = 'Supplemental reserve of 3500 added following the further medical report; general damages reserve now ' + out.reserveGeneralDamages + '.';
} else if (src === 'LogComplaint') {
  out.complaintRef = 'CMP-' + runId;
  out.explanation = 'Complaint logged under reference ' + out.complaintRef + ' with ombudsman referral rights issued to the claimant.';
} else {
  out.claimStatus = 'UnknownRequestSource';
  out.explanation = 'Unrecognised requestSource: ' + src + '.';
}

return out;
